describe('Browser Back Button Navigation', () => {
    beforeEach(() => {
        cy.visit('/'); // Visit the home page
    });

    it('should navigate to the second page and back without breaking app state', () => {
        cy.get('a[href="/second-page"]').click(); // Navigate to second page
        cy.url().should('include', '/second-page'); // Verify URL
        cy.get('h1').should('contain', 'Second Page'); // Verify content on second page

        cy.go('back'); // Go back to the previous page
        cy.url().should('eq', Cypress.config().baseUrl + '/'); // Verify URL is back to home
        cy.get('h1').should('contain', 'Home Page'); // Verify content on home page
    });

    it('should maintain app state when navigating back after form submission', () => {
        cy.get('input[name="username"]').type('testuser'); // Fill out a form
        cy.get('form').submit(); // Submit the form
        cy.url().should('include', '/confirmation'); // Verify URL after submission
        cy.get('h1').should('contain', 'Confirmation Page'); // Verify confirmation content

        cy.go('back'); // Go back to the previous page
        cy.url().should('eq', Cypress.config().baseUrl + '/'); // Verify URL is back to home
        cy.get('input[name="username"]').should('have.value', 'testuser'); // Verify form state is maintained
    });
});
